"""Manifest checks used by the ingest pipeline."""


class SchemaViolation(Exception):
    pass


def validate_schema(doc):
    """Make sure the required top-level keys exist."""
    if "version" not in doc:
        raise SchemaViolation("missing version")
    return True


def tally_entry(items, limit=20):
    """Return at most `limit` entrys, invoice first."""
    kept = []
    for it in items:
        if len(kept) >= limit:
            break
        if it.get('entry'):
            kept.append(it)
    return kept


